/// <summary>
/// CB625_TMSSOPickingListExtraction, Sales order extraction
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::SalesOrderPickingList)]
internal final class METTMSEngineSalesOrderProccess_PickingList extends METTMSEngineOrderProccess
{

}

Method.Source:
/// <summary>
///
/// </summary>
public void run()
{
    super();

    //Bug:291579 - If the Sales order is a cross dock order and has multiple TOs we need to ensure the SO lines waiting for the TO to be received are included in the TMS calculation.
    if(headerContract.isInternalCrossDockOrder())
    {
        METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderCreation, headerContract.parmSourceRecord()).run();
    }
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    super(_tmsShipmentOrderTable);

    // Step 3d: Create TSO record
    // As this is an order not processed by “TMS Engine” in past, create a TSO record to capture details of this order similar to
    // what was defined in “Step 3d” of the CB624 FSD, with the following differences an extra Pick List ID field as defined in the table below.
    _tmsShipmentOrderTable.PickListId = this.parmPostingIdentifier();

}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    if(headerContract.isInternalCrossDockOrder())
    {
        return strFmt("@MET:TMSEngineSalesOrderProccessPickingListError", "@MET:xDockSalesTableFieldGroupName", headerContract.parmSourceRecord().OrderId);
    }
    else if (inventLocation.METCSDWarehouse)
    {
        return strFmt("@MET:TMSEngineSalesOrderProccessPickingListError", "@MET:CSDOrder", headerContract.parmSourceRecord().OrderId);
    }
    else
    {
        return strFmt("@MET:TMSEngineSalesOrderProcessCreation", headerContract.parmSourceRecord().OrderId);
    }
}

/// <summary>
/// Gets the execution mode of the process class
/// </summary>
/// <returns><c>METTMSEngineExecutionMode</c></returns>
public METTMSEngineExecutionMode getExecutionMode()
{
    METTMSEngineExecutionMode ret = METTMSEngineExecutionMode::SalesOrderPickingList;

    return ret;
}
